def get_y(x):
    if x <= pts[0][0]:
        return pts[0][1]
    if x >= pts[-1][0]:
        return pts[-1][1]
    for i in range(len(pts) - 1):
        x1, y1 = pts[i]
        x2, y2 = pts[i+1]
        if x1 <= x <= x2:
            if x1 == x2:
                return y1
            return y1 + (y2 - y1) * (x - x1) / (x2 - x1)
    return pts[-1][1]

# Integrate from X=2 to X=18 using trapezoidal rule with all knot points in between and boundaries
x_start, x_end = 2.0, 18.0
xs = [x_start] + [p[0] for p in pts if x_start < p[0] < x_end] + [x_end]
